      <label>{t('Model profile')}<select aria-label={t('Model profile')} disabled={!!busy} value={profileId} onChange={event => { setProfileId(event.target.value); setPlan(previous => previous ? [{ ...previous[0], profile_id: event.target.value, expected_profile_revision: state.profiles.find(item => item.id === event.target.value)?.revision || 0 }, ...previous.slice(1)] : null); setPersonalKey(''); setPersonalPassword(''); setPersonalCode(''); clearDisclosure(); }}>{state.profiles.map(item => <option value={item.id} key={item.id}>{item.name} · {item.model}</option>)}</select></label>
      {profile && <div className="fc-ai-recipient"><strong>{recipient}</strong><small>{profile.endpoint}</small><span>{profile.model} · {profile.protocol}</span><small>{t(profile.key_source === 'personal' ? 'Uses your personal provider key.' : 'Uses the workspace provider key.')}</small><label><input type="checkbox" checked={profile.consented} disabled={!!busy || !profile.configured || !profile.enabled || !state.globally_enabled} onChange={event => { const enabled = event.target.checked; clearDisclosure(); void perform('Updating model consent…', async version => { await aiRuntimeApi.consent(workspaceId, profile.id, profile.revision, enabled); await refresh(version); }); }} />{t('I opt in to this exact model profile and recipient.')}</label></div>}
