          <button type="button" className="fc-button" onClick={() => void perform('Loading reviewed AI sources…', async version => { const loaded = await loadCopilotChoices(channelId); if (current(version)) { setChoices(loaded.choices); setSecure(loaded.secure); setSelected([]); setReviewedSources({}); clearDisclosure(); } })}>{t('Choose sources')}</button>
          {!!choices.length && <div className="fc-ai-source-list">{choices.map(choice => <label key={choice.key}><input type="checkbox" checked={selected.includes(choice.key)} disabled={!selected.includes(choice.key) && allChosenCount >= 8} onChange={event => { const checked = event.target.checked; clearDisclosure(); if (!checked) { setSelected(previous => previous.filter(key => key !== choice.key)); setReviewedSources(previous => { const next = { ...previous }; delete next[choice.key]; return next; }); return; } void perform('Reviewing selected source text…', async version => { const loaded = await loadCopilotReferencedChoices(channelId, [{ kind: choice.source.kind as 'message' | 'shared_document' | 'file' | 'clip', id: choice.source.id }]); if (!current(version)) return; if (loaded.secure !== secure) throw new Error('Channel encryption changed. Review this request again.'); const fresh = loaded.choices[0], source = await prepareCopilotSource(fresh, channelId, secure); if (!current(version)) return; setChoices(previous => previous.map(item => item.key === choice.key ? { ...fresh, preview: source.text || fresh.preview } : item)); setReviewedSources(previous => ({ ...previous, [choice.key]: source })); setSelected(previous => [...previous, choice.key]); }); }} /><span>{choice.label}<details><summary>{t('Review')}</summary><p>{choice.preview}</p></details></span></label>)}</div>}
          <details><summary>{t('Retrieve context by meaning')}</summary><p>{t('This search stays inside the installation or on this device. Only the results you check can be sent to a model.')}</p><label><input type="checkbox" checked={workspaceRetrieval} onChange={event => { setWorkspaceRetrieval(event.target.checked); setSemanticHits([]); setSemanticSelected([]); setCrossChannelDisclosure(false); clearDisclosure(); }} />{t('Search permitted sources across this workspace')}</label><LabeledWritingField label={t('Find relevant context')}><ScopedCollaborationInput channelId={channelId} allowAI={false} allowReferences={false} as="input" contextId={uid + ':semantic-query'} value={semanticQuery} maxLength={1000} onValueChange={value => setSemanticQuery(value)} /></LabeledWritingField><button type="button" className="fc-button" disabled={!semanticQuery.trim()} onClick={() => void perform('Retrieving current context…', async version => { const found = await semanticSearch(workspaceId, semanticQuery, { scope: secure ? 'encrypted' : 'native', ...(workspaceRetrieval ? {} : { channelId }), limit: 8 }); if (current(version)) { setSemanticHits(found.items); setSemanticSelected([]); setSemanticIncomplete(!found.complete); setCrossChannelDisclosure(false); const channels = await api.getChannels(workspaceId); if (!current(version)) return; setChannelLabels(Object.fromEntries(channels.map(channel => [channel.id, channel.name || t('Conversation')]))); clearDisclosure(); } })}>{t('Find context')}</button>{semanticIncomplete && <p role="status">{t('Some sources could not be included. These results are not a complete inventory.')}</p>}{semanticHits.map(hit => { const key = semanticSourceKey(hit); return <label key={key}><input type="checkbox" checked={semanticSelected.includes(key)} disabled={!semanticSelected.includes(key) && allChosenCount >= 8} onChange={event => { const checked = event.target.checked; setSemanticSelected(previous => checked ? [...previous, key] : previous.filter(id => id !== key)); setCrossChannelDisclosure(false); clearDisclosure(); }} /><span>{hit.title}<small> · #{channelLabels[hit.channel_id] || (hit.channel_id === channelId ? t('Current conversation') : t('Conversation'))}</small><details><summary>{t('Review retrieved text')}</summary><p>{hit.text}</p></details></span></label>; })}</details>
          {semanticHits.some(hit => semanticSelected.includes(semanticSourceKey(hit)) && hit.channel_id !== channelId) && <label><input type="checkbox" checked={crossChannelDisclosure} onChange={event => { setCrossChannelDisclosure(event.target.checked); setDisclose(false); setDiscloseSecure(false); }} />{t('I disclose these reviewed sources from other channels to the selected models. The result stays private until I apply it.')}</label>}
          {externalContext && <aside><strong>{externalContext.label}</strong><p>{t('{count} characters of reviewed tool results are selected for this model request.', { count: externalContext.text.length })}</p><details><summary>{t('Review all returned text')}</summary><pre>{externalContext.text}</pre></details><button type="button" className="fc-button" onClick={() => { setExternalContext(null); clearDisclosure(); }}>{t('Remove tool context')}</button></aside>}
